(function(root){
'use strict';
const C=ShopCore,config=SHOP_CONFIG,browser=typeof document!=='undefined';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${solarIcons[n]||(n==='moon'?'<path d="M20.2 15.1A8.6 8.6 0 0 1 8.9 3.8a8.6 8.6 0 1 0 11.3 11.3Z" fill="none" stroke="currentColor" stroke-width="1.5"/>':solarIcons.arrow)}</svg>`;
const money=n=>n===null?'По запросу':new Intl.NumberFormat('ru-RU').format(n)+' ₽';
const catNames=['iPhone','Mac','iPad','Watch','AirPods'];
const symbol=c=>`<span class="sf" style="--sf:url('assets/sf-${({iPhone:'iphone',Mac:'macbook',iPad:'ipad',Watch:'applewatch',AirPods:'airpods.max'})[c]||'apple.logo'}.png')" aria-hidden="true"></span>`;
const read=(key,otherwise)=>{try{return JSON.parse(localStorage.getItem(key))??otherwise}catch{return otherwise}};
const write=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value))}catch{}};
let cart=browser?C.cleanCart(read('ishop-v2-cart',[]),products):[],favorites=browser?read('ishop-v2-favorites',[]):[],compare=browser?read('ishop-v2-compare',[]):[];
favorites=Array.isArray(favorites)?favorites.filter(id=>products.some(p=>p.id===id)):[];compare=Array.isArray(compare)?compare.filter(id=>products.some(p=>p.id===id)).slice(0,3):[];
let route='home',params=new URLSearchParams(),choice={},galleryIndex=0,undo=null,checkoutData={},checkoutStage=1,filterDraft={},toastTimer,routeObserver;
const filterKeys=['category','scope','q','sort','memory','sim','ram','color','stock','min','max'];
const filters=()=>Object.fromEntries(filterKeys.map(k=>[k,params.get(k)||'']));
const urlFor=p=>`product-${p.id}.html`;
const variantLabel=v=>[v.memory,v.ram&&'ОЗУ '+v.ram,v.sim,v.color].filter(Boolean).join(' · ');
const selectedProduct=()=>products.find(p=>p.id===params.get('id'));
function selectionFor(p){return C.selection(p,choice[p.id]||Object.fromEntries(['memory','color','sim','ram'].map(k=>[k,params.get(k)])))}
function gallery(p,v){const ci=p.colors.indexOf(v.color);return p.gallery?.[ci]||[p.colorImages?.[ci]||p.image]}
const brand=()=>'<a class="brand" href="index.html" aria-label="iShop — главная">iShop<span>devices and accessories</span></a>';
const crumbs=t=>`<div class="breadcrumbs"><a href="index.html">Главная</a><span>/</span>${route==='product'?'<a href="catalog.html">Каталог</a><span>/</span>':''}<span>${esc(t)}</span></div>`;
const button=(label,href,outline=false)=>`<a class="button ${outline?'secondary':''}" href="${href}">${label}${icon('arrow')}</a>`;
const empty=(title,text,action=button('В каталог','catalog.html'))=>`<div class="empty surface"><div class="empty-symbol">${icon('bag')}</div><h2>${title}</h2><p>${text}</p>${action}</div>`;
const liveOrders=()=>!config.demo&&Boolean(config.orderEndpoint)&&Boolean(config.privacyUrl);
function header(){return `<a class="skip-link" href="#main">К содержимому</a><canvas id="matrix" aria-hidden="true"></canvas><div class="utility wrap"><span>${config.city?esc(config.city):'Устройства и аксессуары'}</span><span>${config.demo?'Коллекция для предпросмотра · цены ориентировочные':esc(config.hours||'Подберём ваше устройство')}</span><a href="contacts.html">Контакты ${icon('arrow')}</a></div><header class="site-header wrap">${brand()}<button class="header-search glass" data-open="search-dialog">${icon('search')}<span>Найти устройство, модель или аксессуар</span><kbd>⌘ K</kbd></button><div class="header-actions glass"><button class="icon-button mobile-search" data-open="search-dialog" aria-label="Поиск">${icon('search')}</button><button class="icon-button" data-theme-toggle aria-label="Переключить тему">${icon('moon')}</button><button class="icon-button" data-open="menu-dialog" aria-label="Меню">${icon('menu')}</button></div><a class="header-cart glass" href="cart.html">${icon('bag')}<span>Корзина</span><b data-cart-count>${C.totals(cart).qty||''}</b></a></header><nav class="desktop-nav wrap" aria-label="Категории">${catNames.map(c=>`<a href="catalog.html?category=${c}">${symbol(c)}${c}</a>`).join('')}<a href="guides.html">Помощь с выбором ${icon('arrow')}</a></nav>`}
function footer(){return `<footer class="footer glass"><div class="wrap footer-grid"><div>${brand()}<p>Техника, которая подходит<br>именно вам.</p></div><div><h3>Коллекция</h3>${catNames.map(c=>`<a href="catalog.html?category=${c}">${c}</a>`).join('')}</div><div><h3>Покупателю</h3>${[['delivery','Доставка и оплата'],['warranty','Гарантия и возврат'],['guides','Помощь с выбором'],['contacts','Контакты']].map(([r,t])=>`<a href="${r}.html">${t}</a>`).join('')}</div><div><h3>iShop</h3><a href="about.html">О магазине</a><a href="catalog.html?scope=favorites">Избранное</a><a href="compare.html">Сравнение устройств</a><a href="support.html">Помощь</a></div></div><div class="wrap footer-bottom"><span>© ${new Date().getFullYear()} iShop</span><span>${config.demo?'Предпросмотр · ассортимент и условия требуют подтверждения':esc(config.legalName)}</span><span>Solar · CC BY 4.0</span></div></footer>`}
function dock(){return `<nav class="dock glass" aria-label="Основная навигация"><span class="dock-indicator"></span>${[['home','Главная','index.html','home'],['catalog','Каталог','catalog.html','catalog'],['cart','Корзина','cart.html','bag'],['support','Помощь','#','chat']].map(([id,t,href,i])=>`<${id==='support'?'button':'a'} ${id==='support'?'data-open="help-dialog"':`href="${href}"`} data-nav="${id}" class="dock-item">${icon(i)}<span>${t}</span>${id==='cart'?'<b data-cart-count></b>':''}</${id==='support'?'button':'a'}>`).join('')}</nav><div class="toast" role="status" aria-live="polite"></div>`}
function dialogTop(title){return `<div class="dialog-top"><h2>${title}</h2><button class="icon-button" data-close aria-label="Закрыть">${icon('close')}</button></div>`}
function dialogs(){return `<dialog id="search-dialog" class="glass search-dialog" aria-label="Поиск">${dialogTop('Найдём ваше.')}<form id="search-form"><label class="search-field">${icon('search')}<input id="global-search" type="search" placeholder="Например, айфон 256 или макбук" aria-label="Поисковый запрос" autocomplete="off"></label></form><div id="search-results"></div></dialog><dialog id="menu-dialog" class="glass menu-dialog" aria-label="Меню">${dialogTop('iShop')}<nav class="row-list">${[['catalog','Каталог','catalog'],['about','О магазине','info'],['delivery','Доставка и оплата','delivery'],['warranty','Гарантия и возврат','help'],['guides','Помощь с выбором','search'],['contacts','Контакты','contacts']].map(([r,t,i])=>`<a href="${r}.html">${icon(i)}<span>${t}</span>${icon('arrow')}</a>`).join('')}</nav></dialog><dialog id="filter-dialog" class="glass filter-dialog" aria-label="Фильтры">${dialogTop('Ваши параметры')}<form id="filter-form"><div id="filter-fields"></div><div class="filter-bottom"><button type="button" class="text-button" data-reset-draft>Сбросить</button><button class="button" id="apply-filters">Показать устройства</button></div></form></dialog><dialog id="help-dialog" class="glass help-dialog" aria-label="Помощь">${dialogTop('На вашей стороне.')}<p class="muted">Помощник по выбору. Автоматические ответы, без оператора.</p><div class="messages" id="messages" aria-live="polite"><p class="message">Расскажите, что ищете. Подскажу категорию и параметры, на которые стоит обратить внимание.</p></div><div class="quick-help"><button data-question="Как выбрать память?">Выбрать память</button><button data-question="Как заказать?">Как заказать</button><a href="contacts.html">Связь с магазином</a></div><form id="chat-form" class="chat-form"><input name="question" aria-label="Ваш вопрос" placeholder="Ваш вопрос…" maxlength="500" required><button class="icon-button" aria-label="Отправить вопрос">${icon('arrow')}</button></form></dialog>`}
function card(p){const v=C.variant(p),saved=favorites.includes(p.id);return `<article class="card surface"><div class="card-media"><a class="card-photo" href="${urlFor(p)}" data-card-gallery="${p.id}" aria-label="Открыть ${esc(p.name)}"><img src="assets/${p.image}" alt="${esc(p.name)}" loading="lazy" width="600" height="600" draggable="false"></a><button class="favorite icon-button ${saved?'active':''}" data-favorite="${p.id}" aria-label="${saved?'Убрать из избранного':'Сохранить'} ${esc(p.name)}" aria-pressed="${saved}">${icon(saved?'heartFill':'heart')}</button><div class="card-photo-dots" aria-hidden="true">${gallery(p,v).map((_,i)=>`<i class="${i===0?'active':''}"></i>`).join('')}</div></div><div class="card-body"><div class="card-category">${p.category}<button class="compare-button ${compare.includes(p.id)?'active':''}" data-compare="${p.id}" aria-label="Сравнить ${esc(p.name)}" aria-pressed="${compare.includes(p.id)}">${icon('catalog')}</button></div><a href="${urlFor(p)}"><h3>${p.name}</h3></a><p class="card-spec">${esc(p.highlights?.[0]||p.subtitle)}</p><div class="card-swatches" aria-label="Доступные цвета">${p.colors.map(c=>`<span style="--swatch:${colorHex(c)}" title="${c}"></span>`).join('')}</div><p class="stock"><span></span>Наличие уточняется</p><div class="card-price">${p.memory.length?'от ':''}<strong>${money(p.price)}</strong></div>${p.colors.length>1||p.memory.length?button('Выбрать',urlFor(p)):buyControls(p,v)}</div></article>`}
function home(){return `<section class="hero"><div class="hero-copy"><span class="eyebrow">Новый взгляд на привычное</span><h1>iPhone Duo.<br>Больше мира.</h1><p>Откройте новый формат.<br>Подберите свою конфигурацию.</p>${button('Выбрать Duo',urlFor(products[0]))}<a class="hero-link" href="catalog.html">Вся коллекция ${icon('arrow')}</a></div><div class="hero-visual"><video id="hero-video" autoplay muted loop playsinline preload="metadata" poster="assets/iphone-duo-hero-still.jpg"><source src="assets/iphone-duo-hero.mp4" type="video/mp4"></video></div></section><nav class="category-rail" aria-label="Выберите устройство">${catNames.map(c=>`<a class="glass" href="catalog.html?category=${c}">${symbol(c)}<span>${c}</span>${icon('arrow')}</a>`).join('')}</nav><section class="section"><div class="section-heading"><div><span class="eyebrow">Коллекция iShop</span><h2>Найдите своё.</h2></div><a class="text-link" href="catalog.html">Все устройства ${icon('arrow')}</a></div><div class="cards">${products.map(card).join('')}</div></section><section class="benefits surface"><div>${icon('search')}<h3>Выбор в деталях</h3><p>Память, цвет и главные параметры в одном месте.</p></div><div>${icon('heart')}<h3>Без спешки</h3><p>Сохраните понравившееся и вернитесь к выбору.</p></div><div>${icon('catalog')}<h3>Рядом для сравнения</h3><p>Сопоставьте характеристики до покупки.</p></div></section><section class="promo-grid section"><a class="promo surface" href="product-macbook-air.html"><span class="eyebrow">Для больших идей</span><h2>Лёгкий.<br>С силой M5.</h2><img src="assets/mac-2026.png" alt="MacBook Air" loading="lazy"><span class="text-link">Выбрать Mac ${icon('arrow')}</span></a><a class="promo watch-promo surface" href="product-apple-watch.html"><span class="eyebrow">В вашем ритме</span><h2>Ближе<br>к каждому дню.</h2><img src="assets/watch-black-view-0.jpg" alt="Apple Watch" loading="lazy"><span class="text-link">Посмотреть Watch ${icon('arrow')}</span></a></section>${guideTiles()}<section class="contact-banner glass section"><div><span class="eyebrow">Поможем определиться</span><h2>С чего начнём?</h2><p>Сравните модели или разберитесь в параметрах вместе с помощником.</p></div><div class="stack">${button('Помощь с выбором','guides.html')}<a class="text-link" href="contacts.html">Контакты iShop ${icon('arrow')}</a></div></section>`}
function catalog(){const f=filters(),list=C.filter(products,f,favorites),saved=f.scope==='favorites';return `${crumbs('Каталог')}<div class="page-intro"><span class="eyebrow">${saved?'Ваш личный выбор':'Коллекция iShop'}</span><h1>${saved?'То, что нравится.':'Найдите своё.'}</h1><p>${saved?'Сохранённые устройства всегда под рукой в этом браузере.':'Выберите устройство. Остальное — дело деталей.'}</p></div><label class="search-field glass catalog-search">${icon('search')}<input type="search" id="catalog-query" value="${esc(f.q)}" placeholder="Модель, память или тип устройства" aria-label="Поиск по каталогу"></label><div class="catalog-toolbar"><div class="segmented glass"><span class="scope-indicator ${saved?'right':''}"></span><button data-scope="all" class="${!saved?'active':''}" aria-pressed="${!saved}">ВСЕ</button><button data-scope="favorites" class="${saved?'active':''}" aria-pressed="${saved}" aria-label="Избранное">${icon('heartFill')}</button></div><button class="button secondary filter-toggle" data-open="filter-dialog">${icon('catalog')}Фильтры<span class="filter-count">${filterKeys.filter(k=>!['q','sort','scope'].includes(k)&&f[k]).length||''}</span></button><label class="sort-select glass"><span class="sr-only">Сортировка</span><select id="catalog-sort">${[['','Сортировка'],['asc','Дешевле'],['desc','Дороже'],['name','По названию']].map(([v,t])=>`<option value="${v}" ${f.sort===v?'selected':''}>${t}</option>`).join('')}</select>${icon('arrow')}</label></div><div id="catalog-results">${catalogResults(list,f)}</div>`}
function catalogResults(list,f){const labels={category:'',memory:'Память: ',sim:'SIM: ',ram:'ОЗУ: ',color:'Цвет: ',stock:'Наличие: ',min:'От ',max:'До '};return `<div class="active-filters">${Object.entries(labels).filter(([k])=>f[k]).map(([k,label])=>`<button data-clear-filter="${k}">${label}${esc(k==='stock'?'По запросу':f[k])}${icon('close')}</button>`).join('')}${Object.keys(labels).some(k=>f[k])?'<button class="text-button" data-reset-filters>Сбросить всё</button>':''}</div><div class="results-meta"><span aria-live="polite">Найдено моделей: ${list.length}</span><a href="compare.html" class="text-link">Сравнение <span data-compare-count>${compare.length||''}</span> ${icon('arrow')}</a></div><div class="cards">${list.map(card).join('')}</div>${list.length?'':empty(f.scope==='favorites'&&!favorites.length?'Здесь будет ваш личный выбор':'Пока ничего не нашлось',f.scope==='favorites'&&!favorites.length?'Нажмите на сердечко рядом с устройством, чтобы сохранить его.':'Попробуйте другой запрос или уберите часть параметров.',`<button class="button" data-reset-filters>Показать все устройства ${icon('arrow')}</button>`)}<p class="fine-print">Цены показаны для базовых комплектаций. Наличие и стоимость других вариантов требуют подтверждения.</p>`}
function filterFields(){const f=filterDraft,group=(label,key,values)=>`<fieldset><legend>${label}</legend><div class="filter-options">${[['','Любой'],...values.map(v=>[v,v])].map(([v,t])=>`<label class="option"><input type="radio" name="${key}" value="${esc(v)}" ${f[key]===v||!f[key]&&!v?'checked':''}>${key==='category'&&v?symbol(v):''}<span>${esc(t)}</span></label>`).join('')}</div></fieldset>`;const p=products.filter(p=>!f.category||p.category===f.category),unique=key=>[...new Set(p.flatMap(p=>C.options(p)[key]).filter(Boolean))];return `${group('Устройство','category',catNames)}<fieldset><legend>Бюджет, ₽</legend><div class="two-fields"><label>От<input type="number" min="0" name="min" value="${esc(f.min)}" placeholder="0"></label><label>До<input type="number" min="0" name="max" value="${esc(f.max)}" placeholder="Без ограничения"></label></div><p class="fine-print">По цене базовой комплектации.</p></fieldset>${unique('memory').length?group('Память','memory',unique('memory')):''}${unique('sim').length?group(f.category==='iPad'?'Связь':'SIM / связь','sim',unique('sim')):''}${p.some(p=>p.category==='Mac')?group('Оперативная память Mac','ram',['16 ГБ','24 ГБ','32 ГБ']):''}${group('Цвет','color',unique('color'))}<fieldset><legend>Наличие</legend><p class="muted">Данные об остатках ещё не подключены. Уточняем наличие выбранной комплектации при обращении.</p></fieldset>`}
function buyControls(p,v){const editing=route==='product'&&cart.find(x=>x.key===params.get('edit')&&x.id===p.id);if(editing)return `<button class="button full" data-save-variant>Сохранить изменения ${icon('check')}</button>`;const qty=cart.find(x=>x.key===v.key)?.qty||0;return qty?`<div class="quantity primary"><button data-product-delta="-1" data-id="${p.id}" aria-label="Уменьшить количество">−</button><span aria-live="polite">${qty} в корзине</span><button data-product-delta="1" data-id="${p.id}" aria-label="Добавить ещё">+</button></div>`:`<button class="button full" data-add="${p.id}">${v.price===null?'Добавить в заявку':'В корзину'} ${icon('plus')}</button>`}
function product(){const p=selectedProduct();if(!p)return empty('Устройство не найдено','Посмотрите доступную коллекцию.');const v=C.variant(p,selectionFor(p)),images=gallery(p,v),o=C.options(p);galleryIndex=Math.min(galleryIndex,images.length-1);return `${crumbs(p.name)}<div class="product-layout"><section class="product-gallery" aria-label="Фотографии ${esc(p.name)}"><div class="gallery-stage" data-gallery tabindex="0" role="group" aria-label="Фотографии: листайте свайпом или стрелками клавиатуры"><div class="gallery-track" style="transform:translateX(-${galleryIndex*100}%)">${images.map((src,i)=>`<img src="assets/${src}" alt="${esc(p.name+' '+v.color)}, фото ${i+1}" width="800" height="800" draggable="false">`).join('')}</div><span class="gallery-counter">${galleryIndex+1} / ${images.length}</span><button class="favorite icon-button ${favorites.includes(p.id)?'active':''}" data-favorite="${p.id}" aria-label="Сохранить ${p.name}" aria-pressed="${favorites.includes(p.id)}">${icon(favorites.includes(p.id)?'heartFill':'heart')}</button></div><div class="thumbnails">${images.map((src,i)=>`<button data-gallery-index="${i}" class="${i===galleryIndex?'active':''}" aria-label="Фото ${i+1}" aria-pressed="${i===galleryIndex}"><img src="assets/${src}" alt=""></button>`).join('')}</div></section><section class="product-copy surface"><span class="eyebrow">${p.category} / Коллекция iShop</span><h1>${p.name}</h1><p class="product-tagline">${esc(p.subtitle)}</p><div class="product-highlights">${p.highlights.map(h=>`<span>${esc(h)}</span>`).join('')}</div><div class="product-options">${Object.entries(o).filter(([,values])=>values[0]).map(([key,values])=>`<fieldset><legend>${({memory:'Память',color:'Цвет',sim:p.category==='iPad'?'Связь':'SIM',ram:'Оперативная память'})[key]} <span>${key==='color'?esc(v.color):''}</span></legend><div class="option-list">${values.map(value=>`<button class="option ${v[key]===value?'active':''}" data-option="${key}" data-value="${esc(value)}" aria-pressed="${v[key]===value}">${key==='color'?`<i class="color-dot" style="--swatch:${colorHex(value)}"></i>`:''}${esc(value)}</button>`).join('')}</div></fieldset>`).join('')}</div><div class="purchase-anchor" id="purchase-anchor"><p class="stock"><span></span>Наличие уточняется</p><div class="product-price">${money(v.price)}</div><p class="fine-print">${v.price===null?'Стоимость этой комплектации уточняется отдельно.':'Ориентировочная стоимость выбранной комплектации.'}</p><div data-product-buy>${buyControls(p,v)}</div></div><div class="purchase-notes"><a href="delivery.html">${icon('delivery')}<span>Получение и оплата<small>${config.delivery?esc(config.delivery):'Условия уточняются при подтверждении'}</small></span>${icon('arrow')}</a><a href="warranty.html">${icon('help')}<span>Гарантия и обслуживание<small>Условия для вашего устройства</small></span>${icon('arrow')}</a></div><button class="text-button" data-compare="${p.id}">${icon('catalog')}${compare.includes(p.id)?'Добавлено к сравнению':'Сравнить с другой моделью'}</button></section></div><section class="specs surface section"><div class="section-heading"><div><span class="eyebrow">Ближе к устройству</span><h2>В деталях.</h2></div></div><p>${esc(p.description)}</p><dl>${Object.entries({...p.specs,'Выбранная память':v.memory||'Встроенная','Цвет':v.color,...(v.ram?{'Выбранная ОЗУ':v.ram}:{})}).map(([k,val])=>`<div><dt>${esc(k)}</dt><dd>${esc(val)}</dd></div>`).join('')}</dl><p class="fine-print">Характеристики демонстрационной коллекции. Комплектацию и регион поставки необходимо подтвердить перед покупкой.</p></section><section class="section faq-section"><h2>Перед выбором</h2>${faq('Как выбрать память?','Для приложений и облачного хранения обычно достаточно базового объёма. Если храните видео, большие фотоархивы или рабочие проекты локально, рассмотрите больший объём.')}${faq('Что означает цена «по запросу»?','Для этой конфигурации ещё нет подтверждённой цены. Можно добавить её в подборку; итоговая стоимость требует согласования.')}${faq('Как проверить совместимость аксессуара?','Сопоставьте точную модель и поколение устройства, разъём и требования по мощности. До подтверждения совместимости не добавляйте аксессуар только по внешнему сходству.')}</section><div class="product-sticky glass"><div><strong>${money(v.price)}</strong><small>${esc([v.memory,v.color].filter(Boolean).join(' · '))}</small></div><div data-product-buy>${buyControls(p,v)}</div></div>`}
function totalsHTML(){const t=C.totals(cart);return `<div class="total-row"><span>Устройств</span><b>${t.qty}</b></div><div class="total-row large"><span>${t.unpriced?'Известная часть':'Ориентировочно'}</span><strong>${t.unpriced&&!t.amount?'По запросу':money(t.amount)}</strong></div>${t.unpriced?`<p class="notice">Ещё ${t.unpriced} шт. — цена по запросу. Полный итог пока не определён.</p>`:''}<p class="fine-print">Доставка и окончательная стоимость уточняются при подтверждении.</p>`}
function cartPage(){return `${crumbs('Корзина')}<div class="page-intro"><span class="eyebrow">Всё, что вы выбрали</span><h1>Ваш выбор.</h1></div>${undo?'<div class="undo-bar glass">Товар удалён<button class="text-button" data-undo>Восстановить</button></div>':''}${!cart.length?empty('Ваша корзина пока пуста','Найдите устройство, которое станет вашим.'):`<div class="cart-layout"><div class="cart-items">${cart.map(x=>{const p=products.find(p=>p.id===x.id);return `<article class="cart-row surface"><a class="cart-photo" href="${urlFor(p)}?${new URLSearchParams({memory:x.memory,color:x.color,ram:x.ram,sim:x.sim})}"><img src="assets/${x.image}" alt="${esc(p.name+' '+x.color)}"></a><a class="cart-title" href="${urlFor(p)}"><h2>${p.name}</h2></a><div class="cart-variant"><p>${esc(variantLabel(x))}</p><a class="cart-edit" href="${urlFor(p)}?${new URLSearchParams({memory:x.memory,color:x.color,ram:x.ram,sim:x.sim,edit:x.key})}">Изменить комплектацию</a></div><strong class="cart-price">${money(x.price===null?null:x.price*x.qty)}</strong><div class="quantity glass"><button data-cart-delta="-1" data-key="${esc(x.key)}" aria-label="Уменьшить количество ${p.name}">−</button><span>${x.qty}</span><button data-cart-delta="1" data-key="${esc(x.key)}" aria-label="Увеличить количество ${p.name}">+</button></div><button class="cart-remove icon-button glass" data-remove="${esc(x.key)}" aria-label="Удалить ${p.name}">${icon('close')}</button></article>`}).join('')}<a class="text-link continue-shopping" href="catalog.html">Продолжить выбор ${icon('arrow')}</a></div><aside class="order-summary surface"><h2>Ваша подборка</h2>${totalsHTML()}${button(liveOrders()?'Оформить заявку':'Продолжить оформление','checkout.html')}<p class="fine-print">${liveOrders()?'Без регистрации. Менеджер подтвердит наличие и условия.':'Предпросмотр оформления. Отправка магазину пока не подключена.'}</p><button class="text-button" data-download>Сохранить список</button></aside></div>`}`}
function field(name,label,extra='',type='text'){return `<label class="form-field">${label}<input name="${name}" type="${type}" ${extra} value="${esc(checkoutData[name]||'')}"><span class="field-error" data-error="${name}"></span></label>`}
function checkout(){if(!cart.length&&checkoutStage!==3)return `${crumbs('Оформление')}<div class="page-intro"><h1>Оформление</h1></div>${empty('Сначала выберите устройство','Добавьте нужную комплектацию в корзину.')}`;if(checkoutStage===3)return checkoutResult();return `${crumbs('Оформление')}<div class="page-intro"><span class="eyebrow">Без регистрации</span><h1>${checkoutStage===1?'Как с вами связаться?':'Всё верно?'}</h1><p>${liveOrders()?'Передадим ваш выбор магазину для подтверждения.':'Пример оформления: заявка пока не передаётся магазину.'}</p></div><div class="checkout-steps"><span class="active">1. Контакты</span><i></i><span class="${checkoutStage===2?'active':''}">2. Проверка</span></div><div class="cart-layout"><section class="surface checkout-form">${checkoutStage===1?`<form id="checkout-form" novalidate><h2>Контактные данные</h2><div class="two-fields">${field('name','Ваше имя','autocomplete="given-name" required maxlength="80"')}${field('phone','Телефон','autocomplete="tel" inputmode="tel" required maxlength="24"','tel')}</div><h2>Получение</h2>${field('city','Город','autocomplete="address-level2" required maxlength="120"')}<fieldset><legend class="sr-only">Способ получения</legend><div class="option-list"><label class="option"><input type="radio" name="delivery" value="pickup" ${checkoutData.delivery!=='courier'?'checked':''}>Самовывоз</label><label class="option"><input type="radio" name="delivery" value="courier" ${checkoutData.delivery==='courier'?'checked':''}>Доставка</label></div></fieldset><div id="address-field" ${checkoutData.delivery!=='courier'?'hidden':''}>${field('address','Адрес','autocomplete="street-address" maxlength="250"')}</div><p class="fine-print">${esc(config.delivery||'Адрес самовывоза, доступность доставки и сроки требуют подтверждения магазином.')}</p><label class="form-field">Комментарий <span class="muted">необязательно</span><textarea name="comment" maxlength="500" rows="3" placeholder="Например, удобное время для звонка">${esc(checkoutData.comment||'')}</textarea></label><button class="button full">Проверить подборку ${icon('arrow')}</button></form>`:`<h2>Устройства</h2><div class="review-items">${cart.map(x=>`<div><img src="assets/${x.image}" alt=""><span><strong>${products.find(p=>p.id===x.id).name}</strong><small>${esc(variantLabel(x))} · ${x.qty} шт.</small></span><b>${money(x.price===null?null:x.price*x.qty)}</b></div>`).join('')}</div><a class="text-link" href="cart.html">Изменить подборку ${icon('arrow')}</a><h2>Получатель</h2><p>${esc(checkoutData.name)} · ${esc(checkoutData.phone)}</p><p>${esc(checkoutData.city)} · ${checkoutData.delivery==='courier'?'Доставка: '+esc(checkoutData.address):'Самовывоз'}</p>${checkoutData.comment?`<p>${esc(checkoutData.comment)}</p>`:''}<button class="text-button" data-checkout-back>Изменить данные</button><form id="submit-order">${liveOrders()?`<label class="consent"><input type="checkbox" required name="consent">Согласен с <a href="${esc(config.privacyUrl)}" target="_blank" rel="noopener">условиями обработки данных</a></label>`:'<p class="notice">Данные останутся только в этой вкладке. Заказ и оплата не отправляются.</p>'}<p id="order-error" class="field-error" role="alert"></p><button class="button full" id="submit-button">${liveOrders()?'Отправить заявку':'Подготовить подборку'} ${icon('arrow')}</button></form>`}</section><aside class="order-summary surface"><h2>Итог</h2>${totalsHTML()}<div class="summary-note">${icon('info')}<p>Сначала подтверждение комплектации и условий. Никакой оплаты на этом шаге.</p></div></aside></div>`}
let receipt=null,lastOrderCart=[];
function checkoutResult(){return `<section class="confirmation surface"><div class="confirmation-icon">${icon('bag')}</div><span class="eyebrow">${receipt?'Заявка принята':'Подборка подготовлена'}</span><h1>${receipt?'Спасибо за ваш выбор.':'Всё собрано.'}</h1><p>${receipt?`Номер заявки: <strong>${esc(receipt)}</strong>. Магазин подтвердит наличие, цену и получение.`:'Это предпросмотр. Подборка сохранена в корзине, но ещё не отправлена магазину.'}</p><div class="confirmation-actions">${button('Вернуться в каталог','catalog.html')}<button class="button secondary" data-download>Скачать подборку</button></div><a class="text-link" href="contacts.html">Контакты магазина ${icon('arrow')}</a></section>`}
function faq(title,text){return `<details class="faq glass"><summary>${title}${icon('plus')}</summary><p>${text}</p></details>`}
function guideTiles(){return `<section class="section"><div class="section-heading"><div><span class="eyebrow">Выбор станет проще</span><h2>Разберёмся вместе.</h2></div><a class="text-link" href="guides.html">Все советы ${icon('arrow')}</a></div><div class="guide-grid">${[['memory','Память без сомнений','Что хранить на устройстве, а что — в облаке.','catalog'],['sim','Какая SIM нужна?','Что проверить перед выбором версии iPhone.','info'],['mac','Mac для ваших задач','Процессор, память и приложения, которыми вы пользуетесь.','search']].map(([id,t,d,i])=>`<a class="guide glass" href="guides.html#${id}">${icon(i)}<h3>${t}</h3><p>${d}</p><span class="text-link">Разобраться ${icon('arrow')}</span></a>`).join('')}</div></section>`}
function guides(){return `${crumbs('Помощь с выбором')}<div class="page-intro"><span class="eyebrow">Просто о важном</span><h1>Ваши задачи.<br>Ваше устройство.</h1><p>Несколько ориентиров, чтобы выбрать уверенно.</p></div><div class="guide-articles"><article id="memory" class="surface"><span class="eyebrow">01 / Память</span><h2>Место для вашего мира.</h2><p>Посмотрите, сколько памяти занято на вашем устройстве сейчас. Добавьте запас для новых фотографий, приложений и файлов.</p><ul><li>Облако помогает хранить архив, но для доступа к нему может понадобиться интернет.</li><li>Видео, игры и локальные проекты требуют больше свободного места.</li><li>Память для файлов и оперативная память — разные параметры.</li></ul>${button('Выбрать устройство','catalog.html')}</article><article id="sim" class="surface"><span class="eyebrow">02 / Связь</span><h2>SIM: проверьте версию.</h2><p>Поддержка физической SIM и eSIM зависит от модели и региона поставки. Уточните совместимость eSIM у своего оператора.</p><p>Перед подтверждением покупки сверяйте точную версию, число поддерживаемых линий и возможность переноса номера. Не определяйте SIM только по названию модели.</p>${button('Посмотреть iPhone','catalog.html?category=iPhone')}</article><article id="mac" class="surface"><span class="eyebrow">03 / Работа</span><h2>Начните со своих программ.</h2><p>Составьте список приложений и проверьте их требования. Для больших проектов, монтажа и множества одновременно открытых программ особенно важна оперативная память.</p><p>SSD определяет место для файлов. ОЗУ — объём данных, с которым компьютер работает одновременно. Сравнивайте эти параметры отдельно.</p>${button('Посмотреть Mac','catalog.html?category=Mac')}</article></div>`}
function contacts(){const links=[['Телеграм канал',config.channel,'plain',''],['Чат в Телеграм',config.telegram,'chat',''],['Бот в Телеграм',config.bot,'bot',''],['Телефон',config.phone?'tel:'+config.phone:'','phone',config.phone],['Почта',config.email?'mailto:'+config.email:'','letter',config.email]];return `${crumbs('Контакты')}<div class="page-intro"><span class="eyebrow">iShop рядом</span><h1>На связи с вами.</h1><p>${config.address?esc(config.address):'Выберите удобный способ связи.'}</p></div><div class="contacts-list glass row-list">${links.map(([label,href,i,value])=>`<${href?'a':'div'} ${href?`href="${esc(href)}" ${href.startsWith('https:')?'target="_blank" rel="noopener"':''}`:'aria-disabled="true"'}>${icon(i)}<span><strong>${label}</strong><small>${esc(value||(!href?'Контакт пока не указан':''))}</small></span>${href?icon('arrow'):'<span class="contact-pending">Скоро</span>'}</${href?'a':'div'}>`).join('')}</div>${config.address?`<section class="surface section info-card"><h2>Загляните в iShop</h2><p>${esc(config.address)}</p><p>${esc(config.hours)}</p>${config.mapUrl?button('Построить маршрут',esc(config.mapUrl)):''}</section>`:''}`}
function info(type){const content={about:['Знакомьтесь, iShop.','Техника, которая подходит вашему дню.','Выбирайте в своём ритме.','Мы собрали устройства в одной коллекции: сравнивайте параметры, сохраняйте понравившееся и подбирайте комплектацию под свои задачи.'],delivery:['От выбора до встречи.','Получение и оплата','Доставка и самовывоз',config.delivery||'Город, адрес самовывоза, сроки и стоимость доставки ещё не подтверждены магазином. Эти условия должны быть согласованы до покупки.'],warranty:['Уверенность в деталях.','Гарантия и обслуживание','Перед покупкой',config.warranty||'Срок гарантии, ответственного за обслуживание и порядок обращения необходимо подтвердить для конкретного товара. Условия магазина пока не опубликованы.'],support:['Начнём с вопроса.','Помощь iShop','Поможем сориентироваться.','Откройте руководства, сравните характеристики или задайте вопрос автоматическому помощнику. Для наличия и окончательной цены необходим ответ магазина.']}[type]||[];return `${crumbs(({about:'О магазине',delivery:'Доставка и оплата',warranty:'Гарантия и возврат',support:'Помощь'})[type])}<div class="page-intro"><span class="eyebrow">${content[1]}</span><h1>${content[0]}</h1></div><div class="info-grid"><section class="surface info-card"><h2>${content[2]}</h2><p>${esc(content[3])}</p>${button(type==='support'?'Помощь с выбором':'Перейти к коллекции',type==='support'?'guides.html':'catalog.html')}</section><section class="surface info-card"><h2>${type==='delivery'?'Оплата':type==='warranty'?'Если нужна помощь':'На связи с вашим выбором'}</h2><p>${type==='delivery'?esc(config.payment||'Способы оплаты и окончательная сумма требуют подтверждения. В предпросмотре сайта платежи не принимаются.'):'Контакты магазина, вопросы по устройству и условиям покупки — в одном месте.'}</p>${button('Контакты iShop','contacts.html',true)}</section></div>${type==='support'?`<section class="section faq-section">${faq('Как работает избранное?','Нажмите на сердечко у товара. Подборка хранится в этом браузере; она не синхронизируется между устройствами.')}${faq('Можно ли оформить заказ?','Сейчас доступен предпросмотр оформления. Пока магазин не подключит приём заявок, подборка не отправляется менеджеру.')}${faq('Цены окончательные?','Цены в демонстрационной коллекции ориентировочные. Другие конфигурации могут иметь стоимость по запросу.')}</section>`:''}${type==='about'?guideTiles():''}`}
function comparison(){const list=products.filter(p=>compare.includes(p.id));return `${crumbs('Сравнение')}<div class="page-intro"><span class="eyebrow">Детали рядом</span><h1>Сравните свой выбор.</h1><p>До трёх устройств. Добавляйте их кнопкой сравнения на карточке.</p></div>${!list.length?empty('Что сравним?','Выберите устройства в каталоге.'):`<div class="comparison-scroll surface"><table class="comparison"><thead><tr><th>Характеристики</th>${list.map(p=>`<th><button class="icon-button" data-compare="${p.id}" aria-label="Убрать ${p.name}">${icon('close')}</button><img src="assets/${p.image}" alt=""><a href="${urlFor(p)}">${p.name}</a></th>`).join('')}</tr></thead><tbody>${['Цена от','Память','Цвета',...[...new Set(list.flatMap(p=>Object.keys(p.specs)))].slice(0,16)].map(key=>`<tr><th>${key}</th>${list.map(p=>`<td>${esc(key==='Цена от'?money(p.price):key==='Память'?p.memory.join(', ')||'Встроенная':key==='Цвета'?p.colors.join(', '):p.specs[key]||'—')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}`}
function render(name='home',query=''){route=name;params=new URLSearchParams(query);return ({home,catalog,product,cart:cartPage,checkout,guides,contacts,compare:comparison}[route]||(()=>info(route)))()}
function colorHex(c){return ({'Star White':'#ebe9e3','Night Sky':'#303741',Burgundy:'#64323f',Glacier:'#bed1d9',Silver:'#d2d4d6',Black:'#24252a','Sky Blue':'#b7d1e2',Starlight:'#e6dbc9',Midnight:'#303b4b',White:'#f5f4ef',Blue:'#acc4dc',Purple:'#d2c5de','Space Gray':'#777b81','Light Gold':'#d0c2a3','Dark Bronze':'#665249'})[c]||'#b7b7b7'}
root.ShopUI={render,header,footer,dock,dialogs};
if(!browser)return;
const motionPreference=matchMedia('(prefers-reduced-motion: reduce)'),ease='cubic-bezier(.16,1,.3,1)';
function parseRoute(){const file=location.pathname.split('/').pop()||'index.html',p=new URLSearchParams(location.search);if(file==='favorites.html')p.set('scope','favorites');if(file.startsWith('product-')){p.set('id',file.slice(8,-5));return ['product',p.toString()]}return [({index:'home',favorites:'catalog'})[file.replace('.html','')]||file.replace('.html',''),p.toString()]}
function save(){write('ishop-v2-cart',cart);write('ishop-v2-favorites',favorites);write('ishop-v2-compare',compare);$$('[data-cart-count]').forEach(el=>{el.textContent=C.totals(cart).qty||'';el.hidden=!cart.length});$$('[data-compare-count]').forEach(el=>el.textContent=compare.length||'')}
function toast(message){const el=$('.toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3600)}
function updateDock(){const active=route==='product'||route==='compare'?'catalog':route==='checkout'?'cart':route;$$('[data-nav]').forEach(el=>{const on=el.dataset.nav===active;el.classList.toggle('active',on);on?el.setAttribute('aria-current','page'):el.removeAttribute('aria-current')});const a=$('.dock-item.active');if(a){const ind=$('.dock-indicator');ind.style.width=a.offsetWidth+'px';ind.style.transform=`translateX(${a.offsetLeft}px)`;ind.hidden=false}else $('.dock-indicator').hidden=true}
function mount(){const [name,q]=parseRoute();$('#main').innerHTML=render(name,q);document.body.dataset.page=route;document.title=(route==='home'?'iShop — ваше устройство':route==='product'?selectedProduct()?.name||'Устройство':({catalog:'Каталог',cart:'Корзина',checkout:'Оформление',compare:'Сравнение',contacts:'Контакты',guides:'Помощь с выбором',support:'Помощь',about:'О магазине',delivery:'Доставка и оплата',warranty:'Гарантия'})[route]||'iShop')+(route==='home'?'':' — iShop');save();updateDock();routeObserver?.disconnect();if(route==='product'){routeObserver=new IntersectionObserver(([entry])=>$('.product-sticky')?.classList.toggle('visible',!entry.isIntersecting),{threshold:0});routeObserver.observe($('#purchase-anchor'))}syncVideo();if(location.hash)requestAnimationFrame(()=>$(location.hash)?.scrollIntoView())}
function navigate(href,pop=false){if(!pop){try{sessionStorage.setItem('ishop-scroll:'+location.pathname+location.search,String(scrollY))}catch{};history.pushState({},'',href)}$$('dialog[open]').forEach(d=>d.close());checkoutStage=1;receipt=null;galleryIndex=0;mount();if(pop){let y=0;try{y=Number(sessionStorage.getItem('ishop-scroll:'+location.pathname+location.search)||0)}catch{};requestAnimationFrame(()=>scrollTo(0,y))}else if(!location.hash)scrollTo(0,0)}
function updateURL(f){const url=new URL(location.href);for(const k of filterKeys){f[k]?url.searchParams.set(k,f[k]):url.searchParams.delete(k)}history.replaceState({},'',url);params=new URLSearchParams(url.search)}
function updateResults(){const f=filters();$('#catalog-results').innerHTML=catalogResults(C.filter(products,f,favorites),f)}
function rerender(){const y=scrollY;$('#main').innerHTML=render(route,params.toString());requestAnimationFrame(()=>scrollTo(0,y));save();if(route==='product'){routeObserver?.disconnect();routeObserver?.observe($('#purchase-anchor'))}}
function openPanel(id){const d=$('#'+id);if(id==='filter-dialog'){filterDraft={...filters()};$('#filter-fields').innerHTML=filterFields();countDraft()}if(id==='search-dialog')searchResults($('#global-search').value);d.showModal();if(!motionPreference.matches)d.animate([{opacity:0,transform:'translateY(12px) scale(.96)'},{opacity:1,transform:'translateY(0) scale(1)'}],{duration:420,easing:ease});if(id==='search-dialog')$('#global-search').focus()}
function closePanel(d){if(!d)return;if(motionPreference.matches){d.close();return}d.animate([{opacity:1,transform:'translateY(0)'},{opacity:0,transform:'translateY(8px)'}],{duration:180,easing:ease}).finished.then(()=>d.close()).catch(()=>d.close())}
function searchResults(q){const list=C.filter(products,{q});$('#search-results').innerHTML=`<p class="search-caption">${q?'Найдено моделей: '+list.length:'С чего начнём?'}</p>${list.map(p=>`<a class="search-result" href="${urlFor(p)}"><img src="assets/${p.image}" alt=""><span><strong>${p.name}</strong><small>${esc(p.memory[0]||p.category)} · от ${money(p.price)}</small></span>${icon('arrow')}</a>`).join('')||'<div class="empty"><h3>Попробуем иначе?</h3><p>Введите модель или категорию: айфон, макбук, наушники.</p><a class="text-link" href="catalog.html">Весь каталог</a></div>'}`}
function readDraft(){return {...filterDraft,...Object.fromEntries(new FormData($('#filter-form')))}}
function countDraft(){const f=readDraft(),invalid=f.min&&f.max&&Number(f.min)>Number(f.max);$('#apply-filters').textContent=invalid?'Проверьте диапазон цены':'Показать моделей: '+C.filter(products,f,favorites).length;$('#apply-filters').disabled=Boolean(invalid)}
function syncProductBuy(){const p=selectedProduct();if(!p)return;$$('[data-product-buy]').forEach(el=>el.innerHTML=buyControls(p,C.variant(p,selectionFor(p))));save()}
function snapshotText(){return 'iShop — подборка\n'+(receipt?'Заявка: '+receipt:'Подборка не отправлена магазину')+'\n\n'+(receipt?lastOrderCart:cart).map(x=>`${products.find(p=>p.id===x.id).name}\n${variantLabel(x)}\n${x.qty} шт. × ${money(x.price)}`).join('\n\n')+'\n\nОриентировочная известная сумма: '+money(C.totals(receipt?lastOrderCart:cart).amount)+(C.totals(receipt?lastOrderCart:cart).unpriced?'\nЕсть позиции с ценой по запросу.':'')}
function download(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\uFEFF'+snapshotText()],{type:'text/plain;charset=utf-8'}));a.download='iShop-подборка.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000)}
document.addEventListener('click',e=>{
 const target=e.target,closest=s=>target.closest(s);const link=closest('a[href]');
 if(link&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&!e.altKey&&e.button===0&&link.target!=='_blank'&&!link.download){const u=new URL(link.href,location.href);if(u.origin===location.origin&&u.pathname.endsWith('.html')&&u.pathname.startsWith(location.pathname.slice(0,location.pathname.lastIndexOf('/')+1))){e.preventDefault();navigate(u.href);return}}
 const open=closest('[data-open]');if(open)openPanel(open.dataset.open);if(closest('[data-close]'))closePanel(closest('dialog'));
 if(closest('[data-theme-toggle]')){const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;write('ishop-v2-theme',next);try{localStorage.setItem('ishop-theme',next)}catch{}$('meta[name="theme-color"]').content=next==='dark'?'#100508':'#f7f3f1'}
 const fav=closest('[data-favorite]');if(fav){const id=fav.dataset.favorite;favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];save();if(route==='catalog'&&filters().scope==='favorites')updateResults();else $$(`[data-favorite="${id}"]`).forEach(el=>{el.innerHTML=icon(favorites.includes(id)?'heartFill':'heart');el.classList.toggle('active',favorites.includes(id));el.setAttribute('aria-pressed',String(favorites.includes(id)))});toast(favorites.includes(id)?'Сохранено в избранном':'Удалено из избранного')}
 const cmp=closest('[data-compare]');if(cmp){const id=cmp.dataset.compare;if(compare.includes(id))compare=compare.filter(x=>x!==id);else if(compare.length>=3){toast('В сравнении уже три устройства');return}else compare.push(id);save();if(route==='compare')rerender();else{cmp.classList.toggle('active',compare.includes(id));cmp.setAttribute('aria-pressed',String(compare.includes(id)));toast(compare.includes(id)?'Добавлено к сравнению':'Удалено из сравнения')}}
 const scope=closest('[data-scope]');if(scope){updateURL({...filters(),scope:scope.dataset.scope==='favorites'?'favorites':''});const saved=scope.dataset.scope==='favorites';$('.scope-indicator').classList.toggle('right',saved);$$('[data-scope]').forEach(el=>{const on=el.dataset.scope===scope.dataset.scope;el.classList.toggle('active',on);el.setAttribute('aria-pressed',String(on))});$('.page-intro .eyebrow').textContent=saved?'Ваш личный выбор':'Коллекция iShop';$('.page-intro h1').textContent=saved?'То, что нравится.':'Найдите своё.';$('.page-intro p').textContent=saved?'Сохранённые устройства всегда под рукой в этом браузере.':'Выберите устройство. Остальное — дело деталей.';updateResults()}
 if(closest('[data-reset-filters]')){updateURL({});rerender()}const clear=closest('[data-clear-filter]');if(clear){updateURL({...filters(),[clear.dataset.clearFilter]:''});updateResults()}
 if(closest('[data-reset-draft]')){filterDraft={scope:filters().scope,q:filters().q,sort:filters().sort};$('#filter-fields').innerHTML=filterFields();countDraft()}
 const opt=closest('[data-option]');if(opt){const p=selectedProduct();choice[p.id]={...selectionFor(p),[opt.dataset.option]:opt.dataset.value};galleryIndex=0;const u=new URL(location.href);for(const [k,v]of Object.entries(choice[p.id]))v?u.searchParams.set(k,v):u.searchParams.delete(k);history.replaceState({},'',u);params=new URLSearchParams(u.search);params.set('id',p.id);rerender()}
 if(closest('[data-save-variant]')){const old=cart.find(x=>x.key===params.get('edit')),p=selectedProduct();if(old){cart=C.change(cart.filter(x=>x.key!==old.key),C.variant(p,selectionFor(p)),old.qty);save();navigate('cart.html');toast('Комплектация обновлена')}return}
 const add=closest('[data-add],[data-product-delta]');if(add){const p=products.find(p=>p.id===(add.dataset.add||add.dataset.id)),v=C.variant(p,route==='product'?selectionFor(p):{});cart=C.change(cart,v,Number(add.dataset.productDelta||1));save();if(route==='product')syncProductBuy();else if(route==='catalog')updateResults();else rerender();toast('Корзина обновлена')}
 const qty=closest('[data-cart-delta]');if(qty){const v=cart.find(x=>x.key===qty.dataset.key);if(v.qty===1&&Number(qty.dataset.cartDelta)<0)undo={...v};cart=C.change(cart,v,Number(qty.dataset.cartDelta));save();rerender()}
 const remove=closest('[data-remove]');if(remove){undo={...cart.find(x=>x.key===remove.dataset.remove)};cart=cart.filter(x=>x.key!==undo.key);save();rerender()}
 if(closest('[data-undo]')&&undo){cart=C.change(cart,undo,undo.qty);undo=null;save();rerender()}
 if(closest('[data-download]'))download();if(closest('[data-checkout-back]')){checkoutStage=1;rerender()}
 const index=closest('[data-gallery-index]');if(index)setGallery(Number(index.dataset.galleryIndex));
 const question=closest('[data-question]');if(question)chatAnswer(question.dataset.question);
});
document.addEventListener('input',e=>{if(e.target.id==='global-search')searchResults(e.target.value);if(e.target.id==='catalog-query'){updateURL({...filters(),q:e.target.value});updateResults()}if(e.target.closest('#filter-form'))countDraft()});
document.addEventListener('change',e=>{if(e.target.id==='catalog-sort'){updateURL({...filters(),sort:e.target.value});updateResults()}if(e.target.closest('#filter-form')){filterDraft=readDraft();if(e.target.name==='category'){for(const k of ['memory','sim','ram','color'])filterDraft[k]='';$('#filter-fields').innerHTML=filterFields()}countDraft()}if(e.target.name==='delivery')$('#address-field').hidden=e.target.value!=='courier'});
document.addEventListener('submit',async e=>{const form=e.target;if(!['search-form','filter-form','checkout-form','submit-order','chat-form'].includes(form.id))return;e.preventDefault();
 if(form.id==='search-form')navigate('catalog.html?q='+encodeURIComponent($('#global-search').value));
 if(form.id==='filter-form'){updateURL(readDraft());closePanel($('#filter-dialog'));rerender()}
 if(form.id==='chat-form'){chatAnswer(form.elements.question.value);form.reset()}
 if(form.id==='checkout-form'){checkoutData=Object.fromEntries(new FormData(form));const errors=C.customerErrors(checkoutData);$$('[data-error]').forEach(el=>el.textContent=errors[el.dataset.error]||'');$$('input',form).forEach(el=>el.setAttribute('aria-invalid',String(Boolean(errors[el.name]))));if(Object.keys(errors).length){form.elements[Object.keys(errors)[0]].focus();return}checkoutStage=2;rerender();scrollTo(0,0)}
 if(form.id==='submit-order'){if(!liveOrders()){checkoutStage=3;rerender();scrollTo(0,0);return}const signature=JSON.stringify({checkoutData,cart});if(signature!==pendingSignature){pendingSignature=signature;pendingRequestId=crypto.randomUUID()}const btn=$('#submit-button');btn.disabled=true;btn.textContent='Отправляем…';const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),15000);try{const response=await fetch(config.orderEndpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({customer:checkoutData,items:cart.map(({id,memory,color,sim,ram,qty})=>({id,memory,color,sim,ram,qty})),consent:true,requestId:pendingRequestId}),signal:controller.signal});const result=await response.json();if(!response.ok||typeof result.orderId!=='string'||!result.orderId.trim())throw new Error();receipt=result.orderId;lastOrderCart=cart.map(x=>({...x}));cart=[];save();checkoutStage=3;rerender();scrollTo(0,0);pendingRequestId=crypto.randomUUID()}catch{$('#order-error').textContent='Не удалось подтвердить отправку. Подборка сохранена. Проверьте связь и повторите попытку.';btn.disabled=false;btn.innerHTML='Повторить отправку '+icon('arrow')}finally{clearTimeout(timeout)}}
});
let pendingRequestId=crypto.randomUUID(),pendingSignature='';
function chatAnswer(q){q=q.trim();if(!q)return;let text=/памят|гб|gb/i.test(q)?'Ориентируйтесь на объём ваших файлов. Для облачного хранения подойдёт меньший объём; видео и большие проекты требуют запаса. В разделе «Помощь с выбором» есть подробные ориентиры.':/sim|сим|esim/i.test(q)?'SIM зависит от модели и региона поставки. Проверьте поддержку eSIM у оператора и точную версию устройства перед покупкой.':/заказ|куп|цен|налич|достав|оператор|менеджер/i.test(q)?'В корзине можно собрать комплектацию и пройти оформление. Сейчас это предпросмотр: отправка магазину ещё не подключена, цены и наличие требуют подтверждения.':/мак|mac|работ|ноут/i.test(q)?'Для выбора Mac начните с требований ваших программ. Отдельно сравните оперативную память и SSD. Откройте категорию Mac или руководство по выбору.':'Уточните, что выбираете: телефон, ноутбук, планшет или наушники. Я могу объяснить параметры; актуальное наличие и цену подтверждает магазин.';for(const [cls,value]of [['user',q],['',text]]){const p=document.createElement('p');p.className='message '+cls;p.textContent=value;$('#messages').append(p)}$('#messages').scrollTop=$('#messages').scrollHeight}
function setGallery(index){const p=selectedProduct(),length=gallery(p,selectionFor(p)).length;galleryIndex=Math.max(0,Math.min(length-1,index));$('.gallery-track').style.transform=`translateX(-${galleryIndex*100}%)`;$('.gallery-counter').textContent=`${galleryIndex+1} / ${length}`;$$('[data-gallery-index]').forEach(el=>{const active=Number(el.dataset.galleryIndex)===galleryIndex;el.classList.toggle('active',active);el.setAttribute('aria-pressed',String(active))})}
let swipe=null,suppressClick=false;
document.addEventListener('pointerdown',e=>{const el=e.target.closest('[data-gallery],[data-card-gallery]');if(!el||e.target.closest('button')||e.button!==0)return;swipe={el,x:e.clientX,y:e.clientY};},{passive:true});
document.addEventListener('pointerup',e=>{if(!swipe)return;const {el,x,y}=swipe;swipe=null;const dx=e.clientX-x,dy=e.clientY-y;if(Math.abs(dx)<35||Math.abs(dy)>Math.abs(dx))return;suppressClick=true;setTimeout(()=>suppressClick=false,300);if(el.hasAttribute('data-gallery'))setGallery(galleryIndex+(dx<0?1:-1));else{const p=products.find(p=>p.id===el.dataset.cardGallery),imgs=gallery(p,C.variant(p)),i=(Number(el.dataset.index||0)+(dx<0?1:imgs.length-1))%imgs.length;el.dataset.index=i;$('img',el).src='assets/'+imgs[i];$$('.card-photo-dots i',el.parentElement).forEach((dot,j)=>dot.classList.toggle('active',j===i))}},{passive:true});
document.addEventListener('pointercancel',()=>swipe=null);
document.addEventListener('click',e=>{if(suppressClick&&e.target.closest('[data-card-gallery]')){e.preventDefault();e.stopImmediatePropagation();suppressClick=false}},true);
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openPanel('search-dialog')}if(e.target.closest('[data-gallery]')&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();setGallery(galleryIndex+(e.key==='ArrowRight'?1:-1))}});
$$('dialog').forEach(d=>{d.addEventListener('cancel',e=>{e.preventDefault();closePanel(d)});d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closePanel(d)}})});
function syncVideo(){const v=$('#hero-video');if(!v)return;if(document.hidden||motionPreference.matches)v.pause();else v.play().catch(()=>{})}
document.addEventListener('visibilitychange',syncVideo);motionPreference.addEventListener('change',syncVideo);
addEventListener('popstate',()=>navigate(location.href,true));addEventListener('resize',updateDock,{passive:true});
window.addEventListener('storage',e=>{if(e.key?.startsWith('ishop-v2-')){cart=C.cleanCart(read('ishop-v2-cart',[]),products);favorites=read('ishop-v2-favorites',[]);if(!Array.isArray(favorites))favorites=[];compare=read('ishop-v2-compare',[]);if(!Array.isArray(compare))compare=[];save();if(['cart','catalog','product'].includes(route))rerender()}});
mount();
})(globalThis);
